# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SERBEST CİSİM DİYAGRAMI VE SÜRTÜNME KUVVETİ</text>\n  <rect x="30" y="50" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Yatay Düzlemde Kuvvet Analizi</text>\n  <rect x="140" y="105" width="70" height="45" fill="#93c5fd" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="175" y="132" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">m</text>\n  <line x1="210" y1="127" x2="275" y2="127" stroke="#16a34a" stroke-width="3"/>\n  <text x="285" y="132" font-size="12" font-weight="bold" fill="#16a34a">F</text>\n  <line x1="140" y1="140" x2="85" y2="140" stroke="#dc2626" stroke-width="3"/>\n  <text x="68" y="144" font-size="12" font-weight="bold" fill="#dc2626">f_s</text>\n  <text x="182" y="180" text-anchor="middle" font-size="11.5" fill="#334155">• Yüzey normal kuvveti: N = G = m · g</text>\n  <text x="182" y="200" text-anchor="middle" font-size="11.5" fill="#334155">• Sürtünme: f_s = k · N  ve  F_net = F - f_s = m · a</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Diyagramda m·a (eylemsizlik) vektörü çizilmez!</text>\n  <rect x="365" y="50" width="305" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Statik ve Kinetik Sürtünme</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• Statik sürtünme (f_s,max = k_s · N): Cisim</text>\n  <text x="392" y="123" font-size="11" fill="#475569">harekete geçene kadar uygulanan kuvvete eşittir!</text>\n  <text x="380" y="150" font-size="11.5" fill="#334155">• Örnek: f_s,max = 20 N olan cisme 12 N yatay</text>\n  <text x="392" y="168" font-size="11" font-weight="bold" fill="#b45309">kuvvet uygulanırsa cisim durur ve f_s = 12 N olur.</text>\n  <text x="380" y="195" font-size="11.5" fill="#334155">• Kinetik sürtünme (f_k = k_k · N): Hareket</text>\n  <text x="392" y="213" font-size="11" fill="#475569">sırasında etki eder ve k_s &gt; k_k olduğundan küçüktür.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EĞİK DÜZLEM ÜZERİNDE HAREKET VE BİLEŞENLER</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ağırlık Vektörünün (G = m·g) Bileşenleri</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">• Eğik düzleme paralel bileşen (hareket ettirici):</text>\n  <text x="185" y="128" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">G_x = m · g · sin α</text>\n  <text x="50" y="155" font-size="11.5" fill="#334155">• Eğik düzleme dik bileşen (yüzeye bastıran):</text>\n  <text x="185" y="178" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">G_y = N = m · g · cos α</text>\n  <text x="185" y="212" text-anchor="middle" font-size="11.5" fill="#334155">Sürtünme kuvveti: f_s = k · m · g · cos α</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İvme Bağıntıları (Sürtünmesiz ve Sürtünmeli)</text>\n  <text x="380" y="108" font-size="11.5" font-weight="bold" fill="#1e40af">1) Sürtünmesiz Eğik Düzlemde:</text>\n  <text x="395" y="130" font-size="12" fill="#334155">m · g · sin α = m · a  ⇒  a = g · sin α</text>\n  <text x="395" y="148" font-size="11" fill="#475569">(İvme kütleden bağımsızdır!)</text>\n  <text x="380" y="178" font-size="11.5" font-weight="bold" fill="#1e40af">2) Sürtünmeli Eğik Düzlemde (Aşağı İniş):</text>\n  <text x="395" y="200" font-size="12" fill="#334155">a = g · (sin α - k · cos α)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAĞLI CİSİM SİSTEMLERİ, ATWOOD DÜZENEĞİ VE ETKİ-TEPKİ</text>\n  <rect x="35" y="55" width="300" height="175" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">İple Bağlı Sistemlerde Çözüm Yöntemi</text>\n  <text x="50" y="108" font-size="11.5" fill="#334155">1. Adım: Tüm sistem için ortak ivme bulunur:</text>\n  <text x="185" y="132" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">F_net(sistem) = (m₁ + m₂ + ...) · a</text>\n  <text x="50" y="160" font-size="11.5" fill="#334155">2. Adım: İp gerilmesi (T) için tek bir cisim</text>\n  <text x="62" y="178" font-size="11" fill="#475569">seçilerek serbest cisim diyagramı yazılır.</text>\n  <text x="185" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">İp daima cismi çeker, asla itemez!</text>\n  <rect x="365" y="55" width="300" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Atwood Düzeneği (Sabit Makara)</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• m₁ &gt; m₂ iken net kuvvet ağırlıklar farkıdır:</text>\n  <text x="515" y="135" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">a = (m₁ - m₂) · g / (m₁ + m₂)</text>\n  <text x="380" y="165" font-size="11.5" fill="#334155">• m₁ için: m₁·g - T = m₁·a</text>\n  <text x="380" y="188" font-size="11.5" fill="#334155">• m₂ için: T - m₂·g = m₂·a</text>\n  <text x="515" y="212" text-anchor="middle" font-size="11" fill="#475569">Aynı ipin her noktasında gerilme (T) eşittir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
